UPDATE #temp_Negative SET actionID = 102

INSERT INTO [bodb02].[dbo].[BalanceNegative] (
				[ExecDate]
				,[MatchID]
				,[ActionID]
				,[GroupID]
				,[CustID]
				,[Balance]
				,[StatusID]
				,[Remark]
		)
SELECT GETDATE()
		,42494209
		,102
		,ISNULL(bg.GroupID,1) AS GroupID -- Negative balance defined group Id
		,CustID
		,bal.BalanceNegative
		,0
		,NULL
FROM #temp_Negative bal
	LEFT JOIN dbo.f_Set_NegativeBalance_ActionGroup() AS bg
	ON bg.ActionId = 102
	
	
	